"use server";

import { revalidatePath } from "next/cache";
import { keyPrefixFor, publicUrlForKey } from "@/lib/storage";
import { createNote, getCurrentUser } from "@/lib/users";

export async function createNoteAction(body: string, imageKey?: string) {
  const user = await getCurrentUser();
  if (!user) throw new Error("Unauthorized");
  if (!body.trim()) throw new Error("Note can't be empty");
  // Only accept keys we issued for this user; the URL is built server-side.
  if (imageKey && (!imageKey.startsWith(keyPrefixFor(user.id)) || imageKey.includes(".."))) {
    throw new Error("Invalid image");
  }
  await createNote(user.id, body.trim(), imageKey ? publicUrlForKey(imageKey) : undefined);
  revalidatePath("/dashboard");
}
EOF
cat > src/app/dashboard/note-form.tsx <<'EOF'
"use client";

import { useRef, useState } from "react";
import { createNoteAction } from "./actions";

export function NoteForm() {
  const formRef = useRef<HTMLFormElement>(null);
  const [error, setError] = useState<string>();
  const [busy, setBusy] = useState(false);

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(undefined);
    setBusy(true);
    try {
      const form = new FormData(e.currentTarget);
      const body = String(form.get("body") ?? "");
      const file = form.get("image") as File | null;

      let key: string | undefined;
      if (file && file.size > 0) {
        const res = await fetch("/api/uploads", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ contentType: file.type, size: file.size }),
        });
        const target = await res.json();
        if (!res.ok) throw new Error(target.error ?? "Upload failed");
        const put = await fetch(target.uploadUrl, {
          method: "PUT",
          headers: { "content-type": file.type },
          body: file,
        });
        if (!put.ok) throw new Error("Upload to storage failed");
        key = target.key;
      }

      await createNoteAction(body, key);
      formRef.current?.reset();
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <form ref={formRef} onSubmit={onSubmit} className="mt-2 space-y-2">
      <textarea name="body" required rows={3} className="w-full rounded border p-2 text-sm" />
      <input name="image" type="file" accept="image/png,image/jpeg,image/gif,image/webp" className="text-sm" />
      <div>
        <button disabled={busy} className="rounded bg-black px-3 py-1 text-sm text-white disabled:opacity-50">
          {busy ? "Saving…" : "Add note"}
        </button>
        {error && <span className="ml-3 text-sm text-red-600">{error}</span>}
      </div>
    </form>
  );
}
EOF
