import { randomUUID } from "node:crypto";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

export const MAX_UPLOAD_BYTES = 5 * 1024 * 1024;

const EXTENSIONS: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/gif": "gif",
  "image/webp": "webp",
};

export function keyPrefixFor(userId: string): string {
  return `uploads/${userId}/`;
}

export function publicUrlForKey(key: string): string {
  return `${process.env.S3_PUBLIC_URL}/${key}`;
}

let client: S3Client | undefined;
function s3(): S3Client {
  client ??= new S3Client({
    region: process.env.S3_REGION,
    endpoint: process.env.S3_ENDPOINT || undefined,
    credentials: {
      accessKeyId: process.env.S3_ACCESS_KEY_ID!,
      secretAccessKey: process.env.S3_SECRET_ACCESS_KEY!,
    },
  });
  return client;
}

/** Returns a short-lived presigned PUT URL; type and size are bound into the signature. */
export async function createUploadTarget(
  userId: string,
  contentType: string,
  size: number,
): Promise<{ uploadUrl: string; key: string }> {
  const ext = EXTENSIONS[contentType];
  if (!ext) throw new Error("Only PNG, JPEG, GIF or WebP images are allowed");
  if (!Number.isInteger(size) || size <= 0 || size > MAX_UPLOAD_BYTES) {
    throw new Error("File must be between 1 byte and 5 MB");
  }
  const key = `${keyPrefixFor(userId)}${randomUUID()}.${ext}`;
  const uploadUrl = await getSignedUrl(
    s3(),
    new PutObjectCommand({
      Bucket: process.env.S3_BUCKET,
      Key: key,
      ContentType: contentType,
      ContentLength: size,
    }),
    { expiresIn: 60 },
  );
  return { uploadUrl, key };
}
